CREATE OR REPLACE FUNCTION public.get_my_tasks_data(p_emp_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$ DECLARE   v_today          DATE := CURRENT_DATE;   v_tasks          jsonb; BEGIN   WITH combined_tasks AS (     SELECT       t.task_id AS task_id,       t.task_cd AS task_cd,       t.task_nm AS task_nm,       t.task_desc AS task_desc,       t.task_asgn_to AS task_asgn_to,       t.emp_id AS emp_id,       t.ext_emp_id AS ext_emp_id,       t.task_dep_flg AS task_dep_flg,       t.task_dep_typ AS task_dep_typ,       t.dep_task_id AS dep_task_id,       t.no_of_days AS no_of_days,       t.wrk_days AS wrk_days,       t.chk_flg AS chk_flg,       t.atta_flg AS atta_flg,       t.atta_file_id AS atta_file_id,       t.note_txt AS note_txt,       t.st_dt AS st_dt,       t.end_dt AS end_dt,       t.act_cmp_dt AS act_cmp_dt,       t.prcs_flg AS prcs_flg,       t.prcs_yes_actn AS prcs_yes_actn,       tsm.status_nm AS status_nm,       t.sub_status AS sub_status,       pm.priority_nm AS priority_nm,       t.addl_rem AS addl_rem,       false AS is_individual,       p.prj_nm AS project_name,       m.mlstn_ttl AS milestone_title,       pc_rev.emp_id AS reviewer_id,       TRIM(COALESCE(e_rev.fst_nm,'')||' '||COALESCE(e_rev.lst_nm,'')) AS reviewer_name,       pc_app.emp_id AS approver_id,       TRIM(COALESCE(e_app.fst_nm,'')||' '||COALESCE(e_app.lst_nm,'')) AS approver_name,       chk.total AS chk_total,       chk.completed AS chk_completed     FROM task_live_master t     LEFT JOIN milestone_live_master m ON m.m_id = t.m_id     LEFT JOIN project_live_master p ON p.prj_id = m.prj_id     LEFT JOIN task_status_master tsm ON tsm.status_id = t.task_sts     LEFT JOIN task_priority_master pm ON pm.priority_id = t.priority     LEFT JOIN process_config pc_rev ON pc_rev.task_id = t.task_id AND pc_rev.is_live = true AND pc_rev.ordr_id = 1     LEFT JOIN employee_master e_rev ON e_rev.emp_id = pc_rev.emp_id     LEFT JOIN process_config pc_app ON pc_app.task_id = t.task_id AND pc_app.is_live = true AND pc_app.ordr_id = 2     LEFT JOIN employee_master e_app ON e_app.emp_id = pc_app.emp_id     LEFT JOIN LATERAL (       SELECT         COALESCE(SUM(1 + LENGTH(chk_nm) - LENGTH(REPLACE(chk_nm, ',', ''))), 0) AS total,         COALESCE(SUM(CASE WHEN chk_sts = true THEN 1 + LENGTH(chk_nm) - LENGTH(REPLACE(chk_nm, ',', '')) ELSE 0 END), 0) AS completed       FROM checklist_master       WHERE task_id = t.task_id AND sts = true     ) chk ON true     WHERE (t.emp_id = p_emp_id OR pc_rev.emp_id = p_emp_id OR pc_app.emp_id = p_emp_id OR t.task_id IN (SELECT tm.task_id FROM team_members tm WHERE tm.emp_id = p_emp_id AND tm.task_id IS NOT NULL))      UNION ALL      SELECT       t.emp_task_id AS task_id,       t.task_cd AS task_cd,       t.task_nm AS task_nm,       t.task_desc AS task_desc,       t.task_asgn_to AS task_asgn_to,       t.emp_id AS emp_id,       NULL::bigint AS ext_emp_id,       false AS task_dep_flg,       NULL::varchar AS task_dep_typ,       NULL::bigint AS dep_task_id,       (t.end_dt - t.st_dt) AS no_of_days,       NULL::integer AS wrk_days,       t.chk_flg AS chk_flg,       t.atta_flg AS atta_flg,       NULL::integer AS atta_file_id,       NULL::varchar AS note_txt,       t.st_dt AS st_dt,       t.end_dt AS end_dt,       CASE WHEN tsm.status_nm = 'Closed' THEN t.end_dt ELSE NULL END AS act_cmp_dt,       t.prcs_flg AS prcs_flg,       t.prcs_yes_actn AS prcs_yes_actn,       tsm.status_nm AS status_nm,       t.sub_status AS sub_status,       pm.priority_nm AS priority_nm,       t.remarks AS addl_rem,       true AS is_individual,       'Individual Task' AS project_name,       '-' AS milestone_title,       pc_rev.emp_id AS reviewer_id,       TRIM(COALESCE(e_rev.fst_nm,'')||' '||COALESCE(e_rev.lst_nm,'')) AS reviewer_name,       pc_app.emp_id AS approver_id,       TRIM(COALESCE(e_app.fst_nm,'')||' '||COALESCE(e_app.lst_nm,'')) AS approver_name,       chk.total AS chk_total,       chk.completed AS chk_completed     FROM employee_individual_task_master t     LEFT JOIN task_status_master tsm ON tsm.status_id = t.task_sts     LEFT JOIN task_priority_master pm ON pm.priority_id = t.priority     LEFT JOIN process_config pc_rev ON pc_rev.emp_task_id = t.emp_task_id AND pc_rev.ordr_id = 1     LEFT JOIN employee_master e_rev ON e_rev.emp_id = pc_rev.emp_id     LEFT JOIN process_config pc_app ON pc_app.emp_task_id = t.emp_task_id AND pc_app.ordr_id = 2     LEFT JOIN employee_master e_app ON e_app.emp_id = pc_app.emp_id     LEFT JOIN LATERAL (       SELECT         COALESCE(SUM(1 + LENGTH(chk_nm) - LENGTH(REPLACE(chk_nm, ',', ''))), 0) AS total,         COALESCE(SUM(CASE WHEN chk_sts = true THEN 1 + LENGTH(chk_nm) - LENGTH(REPLACE(chk_nm, ',', '')) ELSE 0 END), 0) AS completed       FROM checklist_master       WHERE emp_task_id = t.emp_task_id AND sts = true     ) chk ON true     WHERE COALESCE(t.sts, true) = true AND (t.emp_id = p_emp_id OR pc_rev.emp_id = p_emp_id OR pc_app.emp_id = p_emp_id OR t.emp_task_id IN (SELECT tm.emp_task_id FROM team_members tm WHERE tm.emp_id = p_emp_id AND tm.emp_task_id IS NOT NULL))   ),   calculated_tasks AS (     SELECT       t.*,       CASE         WHEN t.priority_nm IS NOT NULL THEN           CASE             WHEN UPPER(t.priority_nm) = 'LOW' THEN 'Low'             WHEN UPPER(t.priority_nm) = 'NORMAL' THEN 'Normal'             WHEN UPPER(t.priority_nm) = 'MEDIUM' THEN 'Medium'             WHEN UPPER(t.priority_nm) = 'HIGH' THEN 'High'             WHEN UPPER(t.priority_nm) IN ('CRITICAL', 'ATMOST CRITICAL') THEN 'Critical'             ELSE t.priority_nm           END         WHEN t.end_dt IS NOT NULL THEN           CASE             WHEN (               COALESCE(                 CASE WHEN t.status_nm IN ('CLOSED', 'COMPLETED', 'UNDER_REVIEW', 'SUBMIT_REVIEW')                      THEN COALESCE(t.act_cmp_dt, v_today)                      ELSE v_today                 END, v_today) - t.end_dt             ) = 0 THEN 'High'             WHEN (               COALESCE(                 CASE WHEN t.status_nm IN ('CLOSED', 'COMPLETED', 'UNDER_REVIEW', 'SUBMIT_REVIEW')                      THEN COALESCE(t.act_cmp_dt, v_today)                      ELSE v_today                 END, v_today) - t.end_dt             ) = 1 THEN 'Critical'             WHEN (               COALESCE(                 CASE WHEN t.status_nm IN ('CLOSED', 'COMPLETED', 'UNDER_REVIEW', 'SUBMIT_REVIEW')                      THEN COALESCE(t.act_cmp_dt, v_today)                      ELSE v_today                 END, v_today) - t.end_dt             ) >= 2 THEN 'Critical'             ELSE 'Low'           END         ELSE 'Medium'       END AS final_priority,       CASE         WHEN UPPER(t.status_nm) IN ('CLOSED', 'COMPLETED') THEN 'Closed'         WHEN UPPER(t.status_nm) = 'HOLD' THEN 'Hold'         WHEN UPPER(t.status_nm) = 'DRAFT' THEN 'Draft'         WHEN UPPER(t.status_nm) IN ('WIP', 'IN_PROGRESS', 'UNDER_REVIEW', 'SUBMIT_REVIEW') THEN 'In Progress'         ELSE 'Open'       END AS progress_sts,       CASE         WHEN t.sub_status = 'Under Review' OR UPPER(t.status_nm) IN ('UNDER_REVIEW', 'SUBMIT_REVIEW') THEN 'Under Review'         WHEN t.sub_status = 'Rework' OR UPPER(t.status_nm) = 'REWORK' THEN 'Rework'         WHEN t.sub_status = 'Reassign' OR UPPER(t.status_nm) = 'REASSIGN' THEN 'Reassign'         ELSE 'None'       END AS process_sts,       CASE         WHEN UPPER(t.status_nm) IN ('CLOSED', 'COMPLETED') THEN           CASE             WHEN t.end_dt IS NOT NULL THEN               CASE                 WHEN COALESCE(t.act_cmp_dt, v_today) < t.end_dt THEN 'Lead'                 WHEN COALESCE(t.act_cmp_dt, v_today) = t.end_dt THEN 'On Time'                 ELSE 'Lag'               END             ELSE 'On Time'           END         ELSE           CASE             WHEN t.end_dt IS NOT NULL THEN               CASE                 WHEN v_today < t.end_dt THEN 'On Time'                 WHEN v_today = t.end_dt THEN 'Due Today'                 ELSE 'Overdue'               END             ELSE 'On Time'           END       END AS time_sts     FROM combined_tasks t   ),   final_tasks AS (     SELECT       t.*,       CASE         WHEN NOT COALESCE(t.prcs_flg, false) THEN           CASE             WHEN UPPER(t.status_nm) IN ('CLOSED', 'COMPLETED') THEN 100             WHEN t.chk_total > 0 THEN ROUND((t.chk_completed::numeric / t.chk_total) * 100)::integer             ELSE 0           END         ELSE           CASE             WHEN UPPER(t.status_nm) IN ('CLOSED', 'COMPLETED') THEN 100             WHEN UPPER(t.status_nm) = 'UNDER_REVIEW' THEN 95             WHEN UPPER(t.status_nm) = 'SUBMIT_REVIEW' THEN 90             WHEN t.chk_total > 0 THEN ROUND((t.chk_completed::numeric / t.chk_total) * 100)::integer             ELSE 0           END       END AS progress_pct     FROM calculated_tasks t   )   SELECT COALESCE(jsonb_agg(     jsonb_build_object(       'id', COALESCE(t.task_cd, CASE WHEN t.is_individual THEN 'IND-' || t.task_id ELSE 'TSK-' || t.task_id END),       'taskId', t.task_id,       'isIndividual', t.is_individual,       'title', t.task_nm,       'project', COALESCE(t.project_name, 'Unknown Project'),       'milestone', COALESCE(t.milestone_title, 'Unknown Milestone'),       'priority', t.final_priority,       'dueDate', COALESCE(t.end_dt::text, ''),       'status', t.progress_sts,       'progressSts', t.progress_sts,       'processSts', t.process_sts,       'timeSts', t.time_sts,       'progress', t.progress_pct,       'rawStatus', t.status_nm,       'description', COALESCE(t.task_desc, ''),       'assignedBy', CASE WHEN t.is_individual THEN 'Task Manager' ELSE 'Project Manager' END,       'rawTask', jsonb_build_object(         'taskId', t.task_id,         'mId', CASE WHEN t.is_individual THEN NULL ELSE t.task_id END,         'taskCd', t.task_cd,         'taskNm', t.task_nm,         'taskDesc', t.task_desc,         'empId', t.emp_id,         'extEmpId', t.ext_emp_id,         'taskDepFlg', t.task_dep_flg,         'taskDepTyp', t.task_dep_typ,         'depTaskId', t.dep_task_id,         'noOfDays', t.no_of_days,         'wrkDays', t.wrk_days,         'chkFlg', t.chk_flg,         'attaFlg', t.atta_flg,         'attaFileId', t.atta_file_id,         'noteTxt', t.note_txt,         'stDt', COALESCE(t.st_dt::text, ''),         'endDt', COALESCE(t.end_dt::text, ''),         'actCmpDt', COALESCE(t.act_cmp_dt::text, ''),         'prcsFlg', t.prcs_flg,         'prcsYesActn', t.prcs_yes_actn,         'taskSts', t.status_nm,         'subStatus', t.sub_status,         'priority', t.priority_nm,         'addlRem', t.addl_rem,         'reviewerId', t.reviewer_id,         'approverId', t.approver_id,         'reviewerNm', t.reviewer_name,         'approverNm', t.approver_name       )     )   ), '[]'::jsonb) INTO v_tasks   FROM final_tasks t;    RETURN v_tasks; END; $function$
